  "difficulty": [
    {
      "name": "Journey",
      "what": "A Journey character is required for a Journey world. Research, duplication and world controls change the experience; choose boss settings deliberately."
    },
    {
      "name": "Classic",
      "what": "The standard world difficulty. Character death penalties are a separate choice from world difficulty."
    },
    {
      "name": "Expert",
      "what": "Changes boss behavior and adds Expert rewards. It is a useful foundation for Calamity challenge modes."
    },
    {
      "name": "Master",
      "what": "Higher challenge and additional rewards. Do not assume every Expert strategy survives unchanged."
    },
    {
      "name": "Revengeance",
      "what": "Calamity’s challenge mode layered on an appropriate world difficulty. Boss patterns and Calamity mechanics change; use the difficulty selector in-game."
    },
    {
      "name": "Death",
      "what": "A harder Calamity mode with further encounter changes. Learn Revengeance patterns first if this is your first Calamity playthrough."
    },
    {
      "name": "Multiplayer & this pack",
      "what": "Boss scaling, player count and server settings affect difficulty. Extra accessory slots, pets and QoL options can also change balance."
    }
  ],
  "keybinds": [
    {
      "name": "Recipe Browser",
      "key": "B (suggested)",
      "what": "Find recipes, ingredient uses and crafting stations."
    },
    {
      "name": "Boss Checklist",
      "key": "K (suggested)",
      "what": "Check encounter order, summons and defeat state."
    },
    {
      "name": "Ore Excavator",
      "key": "Grave / tilde, hold (suggested)",
      "what": "Excavate connected allowed tiles; check configured limits."
    },
    {
      "name": "ImproveGame",
      "key": "Choose unused keys per feature",
      "what": "Open its tool menus; avoid conflicts with other QoL mods."
    },
    {
      "name": "Magic Storage",
      "key": "Interact with placed interface",
      "what": "Open the storage/crafting interface; portable tools have their own use conditions."
    },
    {
      "name": "Better Zoom",
      "key": "Choose unused zoom keys",
      "what": "Change the view without covering important boss cues."
    },
    {
      "name": "Summons UI",
      "key": "Choose an unused toggle",
      "what": "Inspect active summons and slot usage."
    },
    {
      "name": "Calamity abilities",
      "key": "Assign Rage, Adrenaline and armor actions",
      "what": "Actions depend on difficulty, equipment and ability state."
    },
    {
      "name": "Helpful Hotkeys — Cycle Ammo",
      "key": "Period (workshop default)",
      "what": "Cycles ammo slots. Hold 1 second to toggle Auto Cycle Ammo Mode. From the Helpful Hotkeys workshop page."
    },
    {
      "name": "Helpful Hotkeys — Auto Torch",
      "key": "Tilde / Backtick (workshop default)",
      "what": "Places a torch from the inventory near the cursor."
    },
    {
      "name": "Helpful Hotkeys — Auto Recall",
      "key": "Home (workshop default)",
      "what": "Uses a Magic Mirror, Cell Phone, or Recall Potion from the inventory."
    },
    {
      "name": "Helpful Hotkeys — Quick Stack to Chests",
      "key": "Minus (workshop default)",
      "what": "Quick-stacks into the open chest, or into nearby chests."
    },
    {
      "name": "Helpful Hotkeys — Smart Quick Stack",
      "key": "Backslash (workshop default)",
      "what": "Quick-stacks matching item families. Favorite stacks you want to keep."
    },
    {
      "name": "Helpful Hotkeys — Quick Buff Favorited Only",
      "key": "B (workshop default)",
      "what": "Drinks only favorited potions. Remap vanilla Quick Buff if you keep this default."
    },
    {
      "name": "Helpful Hotkeys — Query Mod Origin",
      "key": "/ ? (workshop default)",
      "what": "Reports which mod an item, NPC, buff, tile, or wall comes from."
    },
    {
      "name": "Helpful Hotkeys — Quick Use Item #20",
      "key": "L (workshop default)",
      "what": "Uses the item in inventory slot 20 (second row, far right)."
    },
    {
      "name": "Wing Slot Extra",
      "key": "Right-click wings",
      "what": "Moves wings from the inventory into the dedicated wing slot. Right-click vanity wings to swap with the equipped pair."
    },
    {
      "name": "Item Magnet Plus",
      "key": "Left-click / right-click the Item Magnet",
      "what": "Left-click cycles grab range. Right-click shows the current range (or turns it off when the buff icon is disabled in config)."
    },
    {
      "name": "This offline guide",
      "key": "/ · Enter · Esc",
      "what": "Focus search, open an exact item match, close/clear search."
    }
  ],
  "arena": {
    "note": "Start with two or three long platform rows, roughly 15–20 tiles apart, then adapt to the boss. Biome and depth conditions come before convenience.",
    "steps": [
      "Clear obstructions and hazards; test your run, jump and grapple route.",
      "Place a nearby bed and safe housing, but avoid moving so far that the boss despawns.",
      "Check wings, boots, grapple, ammunition and healing before summoning.",
      "Keep boss projectiles visible: reduce cosmetic effects if needed.",
      "Buff stations have progression requirements; use the ones actually available at your checkpoint."
    ],
    "items": [
      {
        "item": "Campfire",
        "what": "Nearby regeneration effect; keep it in range of the fight."
      },
      {
        "item": "Heart Lantern",
        "what": "Hang near the arena for regeneration support."
      },
      {
        "item": "Star in a Bottle",
        "what": "Mana-regeneration support for magic users."
      },
      {
        "item": "Bast Statue",
        "what": "Place nearby for its defensive aura."
      },
      {
        "item": "Sunflower",
        "what": "Place on suitable grass near the surface arena for its movement-related buff."
      },
      {
        "item": "Honey Bucket",
        "what": "Create a small honey dip, with an easy exit; do not trap yourself in slow liquid."
      },
      {
        "item": "Bewitching Table",
        "what": "Interact for the summon buff; check the current tooltip and whether you have unlocked access."
      },
      {
        "item": "Crystal Ball",
        "what": "Interact before a mage fight."
      },
      {
        "item": "Ammo Box",
        "what": "Interact before a ranged fight once available."
      },
      {
        "item": "Sharpening Station",
        "what": "Interact before a melee fight."
      },
      {
        "item": "Slice of Cake",
        "what": "Interact when available for its buff."
      }
    ]
  }
